<?php
require_once 'config.php';require_once 'functions.php';
$dept=trim($_GET['department']??'');$semester=trim($_GET['semester']??'');$rows=[];
$departments=$pdo->query('SELECT DISTINCT department FROM class_routines ORDER BY department')->fetchAll(PDO::FETCH_COLUMN);
$semesters=[];
if($dept!==''){$st=$pdo->prepare('SELECT DISTINCT semester FROM class_routines WHERE department=? ORDER BY semester');$st->execute([$dept]);$semesters=$st->fetchAll(PDO::FETCH_COLUMN);}
if($dept!==''&&$semester!==''){$st=$pdo->prepare('SELECT * FROM class_routines WHERE department=? AND semester=? ORDER BY FIELD(class_day,"Saturday","Sunday","Monday","Tuesday","Wednesday","Thursday","Friday"),start_time');$st->execute([$dept,$semester]);$rows=$st->fetchAll();}
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Class Routine</title><link rel="stylesheet" href="assets/admin.css"></head><body class="admin-body"><main class="routine-public"><div class="public-brand"><span class="brand-icon">SP</span><div><strong>Student Portal</strong><small>CLASS ROUTINE</small></div></div><h1>Find your class routine</h1><p class="muted">Select your department and semester / intake.</p>
<form class="filter-card" method="GET"><div><label>Department</label><select name="department" onchange="this.form.submit()"><option value="">Select department</option><?php foreach($departments as $d): ?><option value="<?= e($d) ?>" <?= $dept===$d?'selected':'' ?>><?= e($d) ?></option><?php endforeach; ?></select></div><div><label>Semester / Intake</label><select name="semester"><option value="">Select semester</option><?php foreach($semesters as $v): ?><option value="<?= e($v) ?>" <?= $semester===$v?'selected':'' ?>><?= e($v) ?></option><?php endforeach; ?></select></div><button class="btn primary">Show Routine</button></form>
<?php if($dept&&$semester): ?><section class="panel public-table"><div class="panel-head"><div><h3><?= e($dept) ?> · <?= e($semester) ?></h3><p>Weekly class schedule</p></div></div><?php if(!$rows): ?><p class="empty">No routine published for this selection.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Day</th><th>Course</th><th>Teacher</th><th>Time</th><th>Room</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['class_day']) ?></td><td><strong><?= e($r['course_code']) ?></strong><small class="sub-id"><?= e($r['course_name']) ?></small></td><td><?= e($r['teacher_name']) ?></td><td><?= e(date('h:i A',strtotime($r['start_time']))) ?> – <?= e(date('h:i A',strtotime($r['end_time']))) ?></td><td><?= e($r['room_no']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php endif; ?>
</main></body></html>
